#!/usr/bin/env python3
"""PPM TWO-SIDED podcast generation: both speakers generated by the same PPM weights (one process, one weight copy, two KV-cache states).

PPM predicts only channel B (channel A is conditioning). Two instances share the weights:
  X: speaker 1 on its channel B, speaker 2 on its channel A  = the eval micro B-iii (dataset orientation, row system prompt)
  Y: speaker 2 on its channel B, speaker 1 on its channel A  = the eval micro A-iii (exact mirror of B-iii incl. its system prompt)
Prefill: system prompt + the first --prompt-s seconds of the conversation, both sides real, teacher-forced, each instance in its own
orientation. Then per conversation step t (position P + t of each instance):
  both instances sample their B text token from hn[t-1] (lane grammar), run the speech tower + 0.6B decoder -> B Mimi frame (t - CD)
  (the two decoders run batched, 2 rows, = two independent batch-1 decodes); then each instance's (text token, codes) at t is written
  into the OTHER instance's channel A at the same conversation position t (the micro layout: depth[c, P + t] = Mimi frame t - CD of
  channel c for both channels, so the code delay CD = 2 carries over unchanged), and both backbones advance one position.
Sampling = infer_ppm defaults (stage-3 reference): text 0.8 / top-k 50, audio 0.8 / top-k 250; no min-p, no audio repetition penalty,
CFG off, bf16. No Whisper / ASR: words are the model's own word lanes.

  python infer_ppm_2side.py --ckpt <ckpt> --rows B-000,B-004 --out <dir> [--prompt-s 20 --gen-s 40]
-> <out>/<row>/: stereo.wav (L = speaker 1, R = speaker 2, 60 s), s1.wav, s2.wav, gt_stereo.wav, gt_s1.wav, gt_s2.wav, words.json,
   transcript.txt, codes.npz, clip_s{1,2}.wav (voice clips of the system prompt, if any), meta.json"""
import argparse
import json
import os
import pickle
import sys
import time

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import infer_ppm as I  # noqa: E402  (sets sys.path / env defaults)
import numpy as np  # noqa: E402
import torch  # noqa: E402
import torch.nn.functional as F  # noqa: E402

CD, DEPTH, CBS, FPS, OFF, TE, PAD, BF = I.CD, I.DEPTH, I.CBS, I.FPS, I.OFF, I.TE, I.PAD, I.BF
log = I.log


class DecoderAR2(I.DecoderAR):
    """I.DecoderAR with a batch of R rows (independent sequences, one per instance)."""

    def __init__(self, dec, c06, dev, R=2):
        super().__init__(dec, c06, dev)
        nkv, hd = c06.num_key_value_heads, c06.head_dim
        self.k = torch.zeros(self.nl, R, nkv, DEPTH + 1, hd, dtype=BF, device=dev)
        self.v = torch.zeros_like(self.k)

    def _run(self, x, s):
        from transformers.models.qwen3.modeling_qwen3 import apply_rotary_pos_emb
        b, n = x.shape[0], x.shape[1]
        cos, sin = self.cos[:, s:s + n], self.sin[:, s:s + n]
        h = x
        for i, L in enumerate(self.d.model.layers):
            at = L.self_attn
            y = L.input_layernorm(h)
            q = at.q_norm(at.q_proj(y).view(b, n, -1, at.head_dim)).transpose(1, 2)
            k = at.k_norm(at.k_proj(y).view(b, n, -1, at.head_dim)).transpose(1, 2)
            v = at.v_proj(y).view(b, n, -1, at.head_dim).transpose(1, 2)
            q, k = apply_rotary_pos_emb(q, k, cos, sin)
            self.k[i, :b, :, s:s + n] = k
            self.v[i, :b, :, s:s + n] = v
            a = F.scaled_dot_product_attention(q, self.k[i, :b, :, :s + n], self.v[i, :b, :, :s + n], is_causal=(n > 1 and s == 0),
                                               scale=at.scaling, enable_gqa=True)
            h = h + at.o_proj(a.transpose(1, 2).reshape(b, n, -1))
            h = h + L.mlp(L.post_attention_layernorm(h))
        return self.d.model.norm(h)

    def __call__(self, hv, cb0, temp, topk, gen, zb=None):
        """hv [R, Hv], cb0 [R] local -> codes [32, R] local."""
        p = self.d.proj(hv)
        x = torch.cat([p[:, None], self.d.cb0_emb(cb0)[:, None]], 1)
        out = [cb0]
        hl = self._run(x, 0)[:, -1]
        for d in range(1, DEPTH):
            c = I.sample_rows((hl @ self.W[d - 1].t()).float(), temp, topk, gen)
            out.append(c)
            if d < DEPTH - 1:
                hl = self._run(self.d.model.embed_tokens(c + (d - 1) * CBS)[:, None], d + 1)[:, -1]
        return torch.stack(out, 0)


def prefix_cards(mic, mimi, out):
    """system prompt of the X orientation (B-iii) -> per speaker {text, clip}; speaker 1 = track 1 (B), speaker 2 = track 0 (A)."""
    P = int(mic["P"])
    ids, dep, pres = mic["ids"][:, :P], mic["depth"][:, :P], mic["present"][:, :P]
    tk = I.tok()
    cards, order = {}, []
    for spk, c in (("s1", 1), ("s2", 0)):
        w = np.flatnonzero((ids[c] < TE) & (pres[c] > 0) & (dep[c, :, 0] < 0))
        txt = tk.decode(ids[c, w].tolist()).strip() if len(w) else ""
        if txt.startswith("system"):                                     # track-1 chat header (<|im_start|>system\n) is not persona text
            txt = txt[len("system"):].strip()
        cf = np.flatnonzero(dep[c, :, 0] >= 0)
        clip = None
        if len(cf):
            codes = (dep[c, cf] - OFF).T
            y = mimi.decode(codes)
            I.write_wav(f"{out}/clip_{spk}.wav", y)
            clip = {"wav": f"clip_{spk}.wav", "seconds": round(len(y) / 24000, 2), "frames": int(len(cf))}
            order.append((int(cf[0]), "clip", spk))
        if txt:
            order.append((int(w[0]), "text", spk))
        cards[spk] = {"text": txt, "n_tokens": int(len(w)), "clip": clip}
    order.sort()
    return cards, [{"kind": k, "spk": s} for _, k, s in order]


def run_row(a, gX, gY, dec2, mimi, row, seed):
    i = int(row.split("-")[1])
    out = f"{a.out}/B-{i:03d}"
    os.makedirs(out, exist_ok=True)
    t_start = time.time()
    mX = pickle.load(open(f"{I.SPEECH_EVAL}/B-{i:03d}.pkl", "rb"))
    mY = pickle.load(open(f"{I.SPEECH_EVAL}/A-{i:03d}.pkl", "rb"))
    PX, PY = int(mX["P"]), int(mY["P"])
    Npc, Ng = int(round(a.prompt_s * FPS)), int(round(a.gen_s * FPS))
    Ntot = Npc + Ng
    nsteps = Ng + CD                                                     # + CD so both speakers' codes cover the full window
    for m_, P_ in ((mX, PX), (mY, PY)):
        assert m_["ids"].shape[1] >= P_ + Ntot + CD, ("row shorter than prompt + gen", row)
        assert P_ + Ntot + CD <= gX.lmax, ("KV cache too short", P_ + Ntot + CD, gX.lmax)
    # mirror check (the A micro must be the exact flip of the B micro in the conversation)
    cx = {k: mX[k][:, PX:PX + Ntot + CD] for k in ("ids", "depth")}
    cy = {k: mY[k][:, PY:PY + Ntot + CD] for k in ("ids", "depth")}
    assert (cx["ids"][::-1] == cy["ids"]).all() and (cx["depth"][::-1] == cy["depth"]).all(), "A micro is not the mirror of B micro"
    prov = json.loads(mX["prov"])
    log(f"[2side] {row}: P X {PX} / Y {PY}, prompt {a.prompt_s}s ({Npc} frames), generate {a.gen_s}s ({Ng} frames), {prov['row_key']}")
    gX.gen.manual_seed(seed)
    S = []
    for g, m_, P_ in ((gX, mX, PX), (gY, mY, PY)):
        ids, depth, present = m_["ids"], m_["depth"], m_["present"]
        Np = P_ + Npc
        hn = g.prefill(ids[:, :Np], depth[:, :Np], present[:, :Np], None, "speech")
        S.append({"g": g, "P": P_, "Np": Np, "lane_b": ids[1].copy(), "dep_b": depth[1].copy(), "lane_a": ids[0].copy(),
                  "dep_a": depth[0].copy(), "present": present, "h": hn[-1:]})
    log(f"[2side] prefill done ({time.time() - t_start:.0f}s)")
    gram = I.Grammar(gX.V, gX.dl, "free" if a.free_text else "nw", a.allow_eob)
    tw = gX.m.tower_s
    ts = []
    for t in range(Npc, Npc + nsteps):
        t1 = time.time()
        hvs, z0s, toks = [], [], []
        for s in S:
            T = s["P"] + t
            z = s["g"].text_logits(s["h"])
            tok = I.sample(z, a.text_temp, a.text_topk, gX.gen, gram.mask(int(s["lane_b"][T - 1])))
            s["lane_b"][T] = tok
            toks.append(tok)
            h = s["g"].ts.run(s["g"].tower_in(tw, [tok], s["dep_b"][T - 1][None], s["h"]), T)
            hv, z0 = s["g"].tower_head(tw, h)
            hvs.append(hv); z0s.append(z0)
        c0 = I.sample_rows(torch.cat(z0s, 0), a.audio_temp, a.audio_topk, gX.gen)
        codes = dec2(torch.cat(hvs, 0), c0, a.audio_temp, a.audio_topk, gX.gen).cpu().numpy().astype(np.int64)   # [32, 2]
        for k, s in enumerate(S):
            s["dep_b"][s["P"] + t] = codes[:, k] + OFF
        for k, s in enumerate(S):                                        # cross-feed: the other instance's B -> my A, same position
            o = S[1 - k]
            T, To = s["P"] + t, o["P"] + t
            s["lane_a"][T] = o["lane_b"][To]
            s["dep_a"][T] = o["dep_b"][To]
        for s in S:
            T = s["P"] + t
            e = s["g"].embed(np.array([[s["lane_a"][T]], [s["lane_b"][T]]], np.int64),
                             np.stack([s["dep_a"][T:T + 1], s["dep_b"][T:T + 1]]), s["present"][:, T:T + 1], None)
            s["h"] = s["g"].hnorm(s["g"].bb.run(e, T))
        ts.append(time.time() - t1)
        if (t - Npc) % 125 == 0:
            log(f"[2side] {row} step {t - Npc}/{nsteps} ({np.mean(ts):.3f}s/step)")
    X, Y = S
    # consistency: X's A == Y's B and vice versa over the whole window
    for s, o in ((X, Y), (Y, X)):
        assert (s["lane_a"][s["P"]:s["P"] + Ntot] == o["lane_b"][o["P"]:o["P"] + Ntot]).all()
        assert (s["dep_a"][s["P"]:s["P"] + Ntot + CD] == o["dep_b"][o["P"]:o["P"] + Ntot + CD]).all()
    # ---- outputs (conversation frame f = position P + CD + f in depth; lane frame f = position P + f)
    c1 = (X["dep_b"][PX + CD:PX + CD + Ntot] - OFF).T
    c2 = (Y["dep_b"][PY + CD:PY + CD + Ntot] - OFF).T
    g1 = (mX["depth"][1, PX + CD:PX + CD + Ntot] - OFF).T
    g2 = (mX["depth"][0, PX + CD:PX + CD + Ntot] - OFF).T
    for c in (c1, c2, g1, g2):
        assert c.shape == (DEPTH, Ntot) and c.min() >= 0 and c.max() < CBS, (c.shape, c.min(), c.max())
    w1, w2, gw1, gw2 = (mimi.decode(c) for c in (c1, c2, g1, g2))

    def stereo(l, r):
        n = max(len(l), len(r))
        st = np.zeros((n, 2), np.float32)
        st[:len(l), 0], st[:len(r), 1] = l, r
        return st
    I.write_wav(f"{out}/s1.wav", w1); I.write_wav(f"{out}/s2.wav", w2); I.write_wav(f"{out}/stereo.wav", stereo(w1, w2))
    I.write_wav(f"{out}/gt_s1.wav", gw1); I.write_wav(f"{out}/gt_s2.wav", gw2); I.write_wav(f"{out}/gt_stereo.wav", stereo(gw1, gw2))
    lw = lambda lane, P_: I.lane_words(lane[:P_ + Ntot], P_, P_, P_ + Npc)  # noqa: E731
    words = {"s1": lw(X["lane_b"], PX), "s2": lw(Y["lane_b"], PY)}
    gtw = {"s1": lw(mX["ids"][1], PX), "s2": lw(mX["ids"][0], PX)}
    tr = I.transcript({"S1": words["s1"], "S2": words["s2"]}, a.prompt_s)
    gtr = I.transcript({"S1": gtw["s1"], "S2": gtw["s2"]}, a.prompt_s)
    open(f"{out}/transcript.txt", "w").write("# both speakers generated after the marker (two PPM instances, shared weights); before it = the real "
                                             "conversation. Text = the models' own word lanes (no ASR).\n" + tr +
                                             "\n\n==== ground truth (same 60 s) ====\n" + gtr + "\n")
    json.dump({"s1": words["s1"], "s2": words["s2"], "gt": gtw, "prompt_s": a.prompt_s,
               "lane_s1": X["lane_b"][PX:PX + Ntot].tolist(), "lane_s2": Y["lane_b"][PY:PY + Ntot].tolist()}, open(f"{out}/words.json", "w"))
    np.savez_compressed(f"{out}/codes.npz", s1=c1.astype(np.int16), s2=c2.astype(np.int16), gt_s1=g1.astype(np.int16), gt_s2=g2.astype(np.int16),
                        lane_s1=X["lane_b"][PX:PX + Ntot], lane_s2=Y["lane_b"][PY:PY + Ntot])
    cards, order = prefix_cards(mX, mimi, out)
    sp = Npc * 1920
    gen = {k: [w for w in words[k] if not w["prompt"]] for k in words}
    meta = {"row": f"B-{i:03d}", "mirror_row": f"A-{i:03d}", "prov": prov, "P_X": PX, "P_Y": PY, "prompt_s": a.prompt_s, "gen_s": a.gen_s,
            "speaker1": f"channel B of B-{i:03d} (data side {prov['chan_B_data_side']})",
            "speaker2": f"channel A of B-{i:03d} (data side {'user' if prov['chan_B_data_side'] == 'assistant' else 'assistant'})",
            "audio": {"s1": I.audio_stats(w1), "s2": I.audio_stats(w2), "s1_gen": I.audio_stats(w1[sp:]), "s2_gen": I.audio_stats(w2[sp:]),
                      "gt_s1": I.audio_stats(gw1), "gt_s2": I.audio_stats(gw2)},
            "gen_lane": {"s1": I.lane_counts(X["lane_b"][PX + Npc:PX + Ntot]), "s2": I.lane_counts(Y["lane_b"][PY + Npc:PY + Ntot])},
            "gen_words": {k: len(v) for k, v in gen.items()}, "gen_text": {k: " ".join(w["text"] for w in v) for k, v in gen.items()},
            "gt_cont_text": {k: " ".join(w["text"] for w in v if not w["prompt"]) for k, v in gtw.items()},
            "gen_cb0_unique": {"s1": int(len(np.unique(c1[0, Npc:]))), "s2": int(len(np.unique(c2[0, Npc:])))},
            "cards": cards, "order": order, "speed_s_per_step": round(float(np.mean(ts)), 4), "wall_s": round(time.time() - t_start, 1),
            "seed": seed, "sampling": {k: getattr(a, k) for k in ("text_temp", "text_topk", "audio_temp", "audio_topk", "free_text", "allow_eob")},
            "min_p": None, "audio_rep_pen": 1.0, "cfg": "off", "dtype": "bf16", "ckpt": a.ckpt,
            "made": time.strftime("%Y-%m-%d %H:%M:%S %Z")}
    json.dump(meta, open(f"{out}/meta.json", "w"), indent=1)
    log(f"[2side] {row} done in {meta['wall_s']}s -> {out}\n  audio {meta['audio']}\n  words {meta['gen_words']}\n  S1: {meta['gen_text']['s1'][:300]}\n"
        f"  S2: {meta['gen_text']['s2'][:300]}")
    open(f"{out}/DONE", "w").write("ok\n")


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--ckpt", required=True)
    ap.add_argument("--rows", required=True, help="comma list of B-iii rows of evalsets/speech_s3")
    ap.add_argument("--out", required=True)
    ap.add_argument("--devs", default="0,1")
    ap.add_argument("--seed", type=int, default=20261012)
    ap.add_argument("--prompt-s", type=float, default=20.0)
    ap.add_argument("--gen-s", type=float, default=40.0)
    ap.add_argument("--text-temp", type=float, default=0.8)
    ap.add_argument("--text-topk", type=int, default=50)
    ap.add_argument("--audio-temp", type=float, default=0.8)
    ap.add_argument("--audio-topk", type=int, default=250)
    ap.add_argument("--free-text", type=int, default=0)
    ap.add_argument("--allow-eob", type=int, default=0)
    a = ap.parse_args()
    assert os.environ.get("GEMM_PRECISION", "bf16") == "bf16", "bf16 only"
    a.pose_temp, a.pose_topk_light = 0.8, 30                              # PPMGen reads these (pose path unused here)
    devs = [torch.device(f"cuda:{int(x)}") for x in a.devs.split(",")]
    torch.cuda.set_device(devs[-1])
    ci = I.ckpt_info(a.ckpt)
    os.makedirs(a.out, exist_ok=True)
    log(f"[2side] ckpt {ci['path']} (step {ci['step']}) rows {a.rows} -> {a.out}")
    torch.manual_seed(a.seed)
    with torch.inference_mode():
        m, ldev, cfgs = I.build_model(ci, devs)
        lmax = 2048 + int(round((a.prompt_s + a.gen_s) * FPS)) + 16
        gX = I.PPMGen(m, ldev, cfgs, devs, lmax, a)
        gY = I.PPMGen(m, ldev, cfgs, devs, lmax, a)
        gY.gen = gX.gen
        dec2 = DecoderAR2(m.dec_s, cfgs[2], devs[-1], 2)
        mimi = I.Mimi(devs[-1])
        for k, row in enumerate(a.rows.split(",")):
            run_row(a, gX, gY, dec2, mimi, row.strip(), a.seed + int(row.split("-")[1]))


if __name__ == "__main__":
    main()
